# November 24, 2026: Atchison, Kansas, on the Missouri River about 44 miles north-west of Kansas City. The Atlas had no
# place there. Facts come from the Kansas Historical Society's register listings for Atchison County (the summary of each
# property), the one Register form read in full (the Burlington freight depot), Wikipedia read as raw text, and the pages of
# the museums, the church and the monastery for hours. Pins checked on the Kansas aerial.
from data_b import N
from data_ma import W
KS=['Kansas Historical Society: National and State Registers, Atchison County listings','https://www.kansashistory.gov/natreg/natreg_listings/search/county:AT']
